// Hit-rate@k + MRR over gold runs (plain JS)
function ragMetrics(runs, k) {
  // runs: [{ goldIds: [...], ranked: [...] }]
  let hits = 0, mrr = 0;
  for (const r of runs) {
    const rank = r.ranked.findIndex((id) => r.goldIds.includes(id));
    if (rank >= 0 && rank < k) { hits++; mrr += 1 / (rank + 1); }
  }
  return { hitRate: hits / runs.length, mrr: mrr / runs.length };
}
// Presence (hit-rate) vs placement (MRR): two numbers, two different fixes.

// Severity gate: money violations veto regardless of averages (plain JS)
function shipGate(scores) {
  // scores: { hitRate, faithfulness, moneyViolations, segments: {sku, paraphrase, vague} }
  if (scores.moneyViolations > 0) return { ship: false, reason: "money-grounding" };
  const weak = Object.entries(scores.segments).filter(([, s]) => s < 0.7).map(([k]) => k);
  if (weak.length) return { ship: false, reason: "weak-segments:" + weak.join(",") };
  if (scores.hitRate < 0.85 || scores.faithfulness < 0.9) return { ship: false, reason: "below-bar" };
  return { ship: true };
}
// Gates compose: vetoes first, segments second, bars last.

